/**
 * @description 矩形を指定された量だけオフセットする。
 *              Offset the Rectangle by the given amount.
 *
 * @param  {Rectangle} rectangle
 * @param  {Point} point
 * @return {void}
 * @method
 * @public
 */
export const execute = (rectangle, point) => {
    rectangle.x += point.x;
    rectangle.y += point.y;
};
